const ico=(n,cls='')=>`<svg class="ico ${cls}" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[n]||''}</svg>`;
const paintIcons=(root=document)=>root.querySelectorAll('i[data-icon]').forEach(i=>{if(!i.firstChild)i.innerHTML=ico(i.dataset.icon);});
let state=null,page=new URLSearchParams(location.hash.slice(1)).get('job')?'studio':(['studio','create','connections','guide'].includes(new URLSearchParams(location.hash.slice(1)).get('page'))?new URLSearchParams(location.hash.slice(1)).get('page'):'filon'),selected=new URLSearchParams(location.hash.slice(1)).get('job'),lastSnapshot='',uploadSlot=null;
// Deep link: /#job=<id> opens that production (bookmarks, support, interface tests).
// Same presence window as the server (75 s): the extension polls every 30 s.
const ONLINE_MS=75000;
// Unsaved story corrections must survive the periodic refresh.
let reviewDirty=false;
// Connector heartbeats change only `seen`; they must not redraw the page (open panels, playing videos).
const renderSnapshot=s=>JSON.stringify({...s,clients:Object.fromEntries(Object.entries(s.clients||{}).map(([id,c])=>[id,{...c,seen:undefined}]))});
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={research:'Recherche',script:'Scénario',characters:'Personnages',images:'Scènes',clips:'Clips Flow',quality:'Contrôle qualité',cover:'Couverture',edit:'Montage',done:'Final'};
const statusLabels={running:'En production',paused:'En pause',attention:'À vérifier',waiting_research:'Références requises',waiting_credit:'Crédits insuffisants',waiting_review:'Histoire à relire',waiting_quota:'Limite atteinte, reprise automatique',waiting_account:'Changement de compte',waiting_night:'En file de nuit',waiting_source:'Analyse de la vidéo d’origine',rendering:'Montage en cours',done:'Prêt à télécharger'};
// A studio restart (update, crash restarted by the launcher) cuts the page for a few seconds: retry quietly
// (owner 06/11/2026: « erreur studio failed to fetch »). Only a network failure is retried, never a refusal.
async function reach(path,init){for(let n=0;;n++){try{return await fetch(path,init)}catch(e){if(n>=4)throw Error('le studio ne répond pas (redémarrage en cours ?). Nouvel essai automatique.');await new Promise(r=>setTimeout(r,1500))}}}
async function api(path,body){const r=await reach(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const b=await r.json();if(!r.ok){if(b.blockers&&typeof showAccountsBlock==='function')showAccountsBlock(b.blockers);const err=Error(b.error||'Erreur');err.blockers=b.blockers;throw err}if(body)window.postMessage({frucht:'wake'},location.origin);return b}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
// A redraw between mouse down and mouse up swallows the click (cards are rebuilt every 4 s while a video is made):
// the refresh waits for the click to finish, the next one draws.
let pressing=false;document.addEventListener('pointerdown',()=>{pressing=true;},true);document.addEventListener('pointerup',()=>setTimeout(()=>{pressing=false;},0),true);document.addEventListener('pointercancel',()=>{pressing=false;},true);
let refreshFails=0;
let loadedVersion=null;
async function refresh(force=false){try{const next=await api('/api/state?view=studio');refreshFails=0;
// A page left open across an update showed the old screens (06/11/2026): a new studio version reloads it, unless typing.
if(next.version){if(!loadedVersion)loadedVersion=next.version;else if(next.version!==loadedVersion&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){location.reload();return;}}const snapshot=renderSnapshot(next);next.filonJobs=next.jobs.filter(j=>j.filon_only);next.jobs=next.jobs.filter(j=>!j.filon_only);state=next;const clients=Object.values(state.clients).filter(c=>!c.disabled&&Date.now()-Date.parse(c.seen)<ONLINE_MS);$('#bridgeBadge').textContent=clients.length?`${clients.length} connecteur(s) en ligne`:'Connecteur à configurer';$('#bridgeBadge').classList.toggle('online',!!clients.length);if((force||snapshot!==lastSnapshot)&&!pressing){lastSnapshot=snapshot;if(!reviewDirty&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))render()}}catch(e){refreshFails=(refreshFails||0)+1;if(refreshFails>=3)toast('Studio inaccessible : '+e.message)}}
const profileOptions=(current)=>`<option value="">Choisir un profil Flow</option>`+state.profiles.map(p=>`<option value="${p.id}" ${current===p.id?'selected':''}>${p.number?"Compte "+p.number+" · ":""}${esc(p.label)} · ${p.balance} crédits</option>`).join('');
function intro(title,sub,button=true){return `<div class="intro"><div><h1>${title}</h1><p>${sub}</p></div>${button?`<button class="primary" data-action="new">${ico('plus')} Créer une vidéo</button>`:''}</div>`}
function list(){if(!state.jobs.length)return `<div class="empty"><div class="empty-symbol">${ico('film')}</div><h3>Votre prochaine histoire commence ici</h3><p>Donnez une direction à l’IA. Le studio commence par rechercher des références, puis prépare votre épisode original.</p><button class="secondary" data-action="new">${ico('create')} Créer mon premier épisode</button></div>`;return `<div class="project-list">${state.jobs.map(j=>`<button class="project ${selected===j.id?'selected':''}" data-job="${j.id}">${(()=>{const f=j.cover||(j.scenes||[]).map(x=>x.image).filter(Boolean).map(x=>assetURL(j,x))[0]||(j.characters||[]).map(c=>c.file).filter(Boolean).map(x=>assetURL(j,x))[0];return f?`<img class="project-thumb" src="${f}" alt="Aperçu">`:`<span class="project-thumb">${ico('film')}</span>`})()}<span class="project-content"><b>${esc(j.title)}</b><small>${j.config.provider==='claude'?'Claude':'ChatGPT'} · ${j.config.scene_count*(j.config.clip_seconds||8)} s · ${esc(j.config.language||"Deutsch")} · ${({'gemini_omni_flash':'Omni Flash','veo_3_1_lite':'Veo Lite','veo_3_1_fast':'Veo Fast','veo_3_1_quality':'Veo Quality'}[j.config.flow_model]||'Flow')} · ${esc(labels[j.stage])}</small></span><span class="pill ${j.status}">${esc(statusLabels[j.status]||j.status)}</span></button>`).join('')}</div>`}
// P2-10: night queue, one production at a time, with its log.
function nightPanel(){const n=state.night||{ids:[],log:[],active:false};if(!n.ids.length&&!n.log.length)return '';const title=id=>esc(state.jobs.find(j=>j.id===id)?.title||id);return `<section class="panel night"><div class="section-title"><h2>File de nuit ${n.active?'· en cours':'· arrêtée'}</h2><div class="actions">${n.active?'<button class="secondary" data-night="stop">Arrêter la file</button>':n.ids.length?'<button class="primary" data-night="start">Démarrer la file de nuit</button>':''}</div></div><p class="hint">Une production à la fois. Échecs réessayables relancés jusqu’à 3 fois ; limites et crédits attendus ; une production qui a besoin de vous est retirée avec la raison. Le PC ne se met pas en veille pendant la file (Windows).</p><ol>${n.ids.map(id=>`<li>${title(id)} · ${esc(statusLabels[state.jobs.find(j=>j.id===id)?.status]||'')}${n.failures?.[id]?` · essais ${n.failures[id]}/3`:''}</li>`).join('')}</ol>${n.log.length?`<details><summary>Journal de la file</summary>${n.log.slice(-15).reverse().map(x=>`<p class="hint"><time>${esc(new Date(x.at).toLocaleTimeString('fr-FR'))}</time> ${esc(x.text)}</p>`).join('')}</details>`:''}</section>`}
// Atelier-like "Le Filon": every TikTok reference found by the research, best signal first.
// Official TikTok embed player (oEmbed): real videos in Le Filon, muted, looping, no account needed.
const tiktokId=u=>String(u||'').match(/\/video\/(\d{5,25})/)?.[1]||null;
const player=id=>`<iframe class="filon-player" src="https://www.tiktok.com/player/v1/${id}?autoplay=1&muted=1&loop=1&controls=0&progress_bar=0&play_button=0&volume_control=0&fullscreen_button=0&timestamp=0&music_info=0&description=0&rel=0&native_context_menu=0&closed_caption=0" loading="lazy" allow="autoplay; encrypted-media" title="Aperçu TikTok" onload="setTimeout(()=>this.classList.add('ready'),1800)"></iframe>`;
function filon(){const seen=new Map();for(const j of [...state.jobs,...(state.filonJobs||[])])for(const c of j.candidates||[])if(!seen.has(c.url)||(c.score||0)>(seen.get(c.url).score||0))seen.set(c.url,c);
const rows=[...seen.values()].sort((a,b)=>(b.score||0)-(a.score||0)).slice(0,60);const fmt=n=>n==null?'—':n>=1e6?(n/1e6).toFixed(1).replace('.0','')+' M':n>=1e3?Math.round(n/1e3)+' k':String(Math.round(n));
const running=(state.filonJobs||[]).find(j=>!['done','attention','paused'].includes(j.status));const last=state.settings.filon_refreshed;
return `<div class="intro"><div><h1>Le Filon</h1><p>Ce qui marche dans ta niche. Glisse une vidéo sur la zone de création, colle un lien TikTok n’importe où, ou clique pour créer.</p></div><div class="actions"><label class="check switch"><input type="checkbox" id="filonAuto" ${state.settings.filon_auto?'checked':''}> Actualiser toutes les 2 h</label><button class="primary" data-filon-refresh="1" ${running?'disabled':''}>${ico('refresh',running?'spin':'')} ${running?'Actualisation…':'Actualiser'}</button></div></div>
<div class="dropzone" data-drop="create">${ico('create')}<div><b>Créer une vidéo</b><span>Dépose une vidéo du Filon ici, ou colle un lien TikTok (Ctrl+V)</span></div><button class="secondary" data-action="new">Partir d’une idée</button></div>
<p class="hint filon-meta">${rows.length} vidéo(s) relevée(s)${last?' · dernière actualisation '+new Date(last).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'}):''}${running?' · recherche TikTok en cours dans la fenêtre FruchtDrama':''}</p>
${rows.length?`<div class="filon-grid">${rows.map((c,k)=>`<article class="filon-card" draggable="true" data-url="${esc(c.url)}" style="--i:${k%12}"><div class="filon-media" data-video="${esc(tiktokId(c.url)||'')}">${c.thumb?`<img src="${esc(c.thumb)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.remove()">`:''}${k<8&&tiktokId(c.url)?player(tiktokId(c.url)):''}<span class="filon-rank">${k+1}</span><div class="filon-stats">${c.metric_kind==='views'?ico('eye')+' '+fmt(c.views):c.metric_kind==='likes'?ico('heart')+' '+fmt(c.likes):''}${c.age_days?`<span>${esc(c.age_days)} j</span>`:''}</div><div class="filon-hover"><button class="primary" data-action="new" data-source="${esc(c.url)}">${ico('create')} Créer d’après</button><button class="secondary" data-copy="${esc(c.url)}">Copier le lien</button><a class="secondary" href="${esc(c.url)}" target="_blank" rel="noopener">${ico('external')} Ouvrir</a></div></div><p class="filon-title">${esc((c.title||c.url).replace(/\s+/g,' ').slice(0,110))}</p></article>`).join('')}</div>`:`<div class="filon-empty">${Array.from({length:8},(_,k)=>`<div class="skeleton" style="--i:${k}"></div>`).join('')}<p>Aucune vidéo relevée. Clique sur <b>Actualiser</b> : la recherche TikTok s’ouvre dans la fenêtre FruchtDrama (compte TikTok connecté conseillé).</p></div>`}`}
function studio(){const done=state.jobs.filter(j=>j.status==='done').length,active=state.jobs.filter(j=>j.status!=='done').length,balance=state.profiles.reduce((a,p)=>a+p.balance,0);return intro('Le studio de vos histoires.','De la première idée au dernier rebondissement.')+`${nightPanel()}<section class="hero"><div class="hero-copy"><span class="eyebrow">VOTRE UNIVERS, VOTRE SIGNATURE</span><h2>Petits fruits.<br>Grandes histoires.</h2><span class="badge">MULTILINGUE &nbsp;·&nbsp; ANIMATION 3D &nbsp;·&nbsp; 9:16</span></div><div class="hero-art"><img src="/mascot.png" alt="Mascotte fraise expressive en animation 3D"><div class="floating"><b>Une histoire originale</b>Un nouveau twist à chaque épisode</div><div class="floating bottom">Votre univers reste cohérent</div></div><span class="hero-index">FRUCHTDRAMA / STUDIO 01</span></section><div class="stats"><div class="stat"><span class="stat-icon">${ico('library')}</span><div><small>Épisodes terminés</small><strong>${done}<span>dans votre bibliothèque</span></strong></div></div><div class="stat"><span class="stat-icon">${ico('clock')}</span><div><small>Productions ouvertes</small><strong>${active}<span>à suivre dans le studio</span></strong></div></div><div class="stat"><span class="stat-icon">${ico('coins')}</span><div><small>Crédits déclarés · ${state.profiles.length} profil(s)</small><strong>${balance}<span>solde réel à vérifier dans Flow</span></strong></div></div></div><div class="columns"><section class="panel"><div class="section-title"><h3>Vos productions</h3><span class="muted">${state.jobs.length} épisode(s)</span></div>${list()}</section><section class="panel"><h3>Une chaîne, neuf étapes.</h3><div class="process"><div class="process-row"><span>01</span><div><b>Repérer une histoire qui résonne</b><small>Recherche et comparaison des références</small></div></div><div class="process-row"><span>02</span><div><b>Créer votre version originale</b><small>Scénario, personnages et scènes</small></div></div><div class="process-row"><span>03</span><div><b>Donner vie à l’histoire</b><small>Clips parlés, montage et couverture</small></div></div></div><div class="notice">Connecteurs navigateur expérimentaux. Les comptes IA et Flow restent indépendants.</div><button class="secondary wide" style="margin-top:15px" data-page="connections">Configurer mes comptes</button></section></div>${selected?detail():''}`}
function editorialReview(j){const c=j.script?.creative_selection;if(!Array.isArray(c?.candidates))return '';return `<details><summary>Choix éditorial · 5 concepts comparés</summary><p class="hint">Notes proposées par l’IA pour comparer les idées ; elles ne prédisent pas les vues.</p>${c.candidates.map((x,i)=>`<div class="profile-card"><b>${i===c.selected_index?ico('check')+' Retenu · ':''}${esc(x.title)}</b><p>${esc(x.hook)}</p><small>${esc(x.conflict)} · ${esc(x.setting)}</small></div>`).join('')}<p class="hint">${esc(c.reason||'')}</p></details>`}
function qualityReview(j){const q=j.quality_report;if(!q)return '';const issues=[...(q.hard_errors||[]),...(q.warnings||[])];if(!issues.length&&!(j.stage==='quality'&&j.status==='attention'))return '';  // 0.1.102: shown only when something needs you
return `<details open><summary>Contrôle qualité des clips</summary><p class="hint">${esc(({pass:'Contrôles locaux réussis',review_required:'Vérification nécessaire',checked:'Contrôles disponibles terminés',approved_with_reservations:'Validé avec réserves'})[q.status]||q.status)} · Les images échantillonnées ne certifient pas les lèvres ni l’identité des voix.</p>${issues.map(x=>`<p>${esc(x)}</p>`).join('')}${q.visual?`<p><b>Cohérence entre scènes :</b> ${esc(q.visual.continuity.detail)}</p>${q.visual.scenes.map(x=>`<p>Scène ${x.index+1} · ${esc(({pass:'Conforme sur les images observées',issue:'Problème détecté',uncertain:'Incertain'})[x.status]||x.status)} : ${esc(x.detail)}</p>`).join('')}`:''}<a class="secondary" href="/media/${j.id}/${q.visual?'quality-report':'quality-local'}.json?download=1" download>${ico('download')} Rapport qualité</a>${j.stage==='quality'&&j.status==='attention'&&!q.hard_errors?.length?`<p class="hint">Vérifiez les clips ci-dessous avant de confirmer. Cette validation conserve les clips et ne lance aucune nouvelle génération Flow.</p><button class="secondary" data-command="${q.visual?'approve_quality':'approve_speech'}">${q.visual?'J’ai vérifié les réserves, continuer':'J’ai écouté les dialogues, continuer la revue visuelle'}</button>`:''}</details>`}
function detail(){const j=state.jobs.find(j=>j.id===selected);if(!j)return '';const task=state.tasks.find(t=>t.job===j.id&&['queued','claimed'].includes(t.status));const steps=Object.keys(labels),idx=steps.indexOf(j.stage);return `<section class="panel detail"><div class="detail-head"><div><span class="eyebrow">PRODUCTION ${j.id.slice(0,6).toUpperCase()}</span><h2 style="margin-top:8px">${esc(j.title)}</h2></div><div class="actions"><button class="secondary" data-command="pause">Pause</button><button class="secondary" data-command="resume">Reprendre</button>${j.status!=='done'?(state.night?.ids||[]).includes(j.id)?'<button class="secondary" data-night="remove">Retirer de la file de nuit</button>':'<button class="secondary" data-night="add">Ajouter à la file de nuit</button>':''}<button class="secondary" data-delete-job="1">Supprimer…</button></div></div><div class="timeline">${steps.map((s,i)=>`<div class="step ${i<idx?'past':i===idx?'current':''}">${String(i+1).padStart(2,'0')} ${labels[s]}</div>`).join('')}</div><div class="detail-note">${esc(statusLabels[j.status]||j.status)}${task?` · ${esc(task.slot)} ${task.status==='claimed'?'est en cours dans le navigateur':'attend un connecteur disponible'}`:''}</div>${dryRunNotice(j)}${humanNotice(j)}${accountNotice(j)}${uncertainClips(j)}${scriptReview(j)}<div class="form-grid">${(j.config.video_engine||'flow')!=='flow'?`<p class="hint engine-badge">Moteur vidéo : <b>${esc({grok:'Grok Imagine'}[j.config.video_engine]||j.config.video_engine)}</b> · comptes dans Connexions</p>`:''}<label ${(j.config.video_engine||'flow')!=='flow'?'hidden':''}>Profil Flow de cette production<select id="jobProfile">${profileOptions(j.flow_profile)}</select><span class="hint">Choisir un profil, puis Reprendre. Les clips déjà reçus restent conservés.</span></label><label>IA de scénario<select id="jobProvider"><option value="chatgpt" ${j.config.provider==='chatgpt'?'selected':''}>ChatGPT</option><option value="claude" ${j.config.provider==='claude'?'selected':''}>Claude</option></select><span class="hint">Les images restent confiées à ChatGPT ; changer l’IA ne supprime aucun média.</span></label></div>${j.selected?`<p class="hint">Référence retenue : <a href="${esc(j.selected.url)}" target="_blank" rel="noreferrer">ouvrir TikTok ${ico('external')}</a> · ${esc(j.selected.basis)}. Ce choix ne garantit pas la viralité.</p>`:''}${editorialReview(j)}${qualityReview(j)}${j.candidates.length?`<details><summary>Références comparées (${j.candidates.length})</summary>${j.candidates.map(c=>`<div class="candidate"><div><a href="${esc(c.url)}" target="_blank" rel="noreferrer">${esc(c.title.slice(0,100)||c.url)}</a><small>${esc(c.basis)} · ${c.views??c.likes??c.signal??'inconnu'} · observé le ${new Date(c.observed_at).toLocaleDateString('fr')}</small></div><button class="secondary" data-source="${esc(c.url)}">Choisir</button></div>`).join('')}</details>`:''}<details><summary>Ajouter des références vérifiées</summary><p class="hint">Un lien TikTok par ligne, puis « | » et le nombre de vues, si connu. Ne saisissez pas des likes à la place des vues.</p><textarea id="researchInput" rows="3" placeholder="https://www.tiktok.com/@compte/video/123456789 | 120000"></textarea><button class="secondary" data-action="research">Enregistrer les références</button></details>${task?`<details><summary>Prompt de la tâche · copie manuelle possible</summary><pre>${esc(task.payload.prompt||task.payload.query)}</pre><button class="secondary" data-copy-task="${task.id}">Copier le prompt</button></details>`:''}<details><summary>Importer un scénario JSON</summary><p class="hint">Pour reprendre une réponse ChatGPT/Claude ou contourner une panne du connecteur. Le studio valide la structure et les locuteurs.</p><textarea id="scriptInput" rows="5" placeholder="Collez ici le JSON du scénario"></textarea><button class="secondary" data-action="script">Valider le scénario</button>${j.script?`<pre>${esc(JSON.stringify(j.script,null,2))}</pre>`:''}</details>${j.characters.length?`<h3 style="margin-top:25px">Personnages</h3><div class="assets">${usesSheet(j)?asset(j,j.character_sheet_file,'Feuille commune : '+j.characters.map(c=>c.name).join(', '),'characters'):j.characters.map(c=>asset(j,c.file,c.name,'character:'+c.id)).join('')}</div><h3>Scènes et clips</h3><div class="assets">${j.scenes.map((s,i)=>`<div class="asset">${s.image?`<img src="${assetURL(j,s.image)}" alt="Scène ${i+1}">`:`<div class="asset-placeholder">${ico('image')}</div>`}<b>Scène ${i+1} · ${esc(j.config.clip_seconds||8)} s</b><button class="secondary" data-upload="image:${i}" data-type="image">${s.image?'Remplacer':'Importer'} l’image</button>${s.image?`<button class="secondary redo" data-redo="image:${i}" data-has-clip="${s.clip?1:0}">Refaire l’image…</button>`:''}${s.clip?`<video src="${assetURL(j,s.clip)}" controls preload="metadata"></video>`:''}<button class="secondary" style="margin-top:7px" data-upload="clip:${i}" data-type="video">${s.clip?'Remplacer':'Importer'} le clip</button>${s.clip?`<button class="secondary redo" data-redo="clip:${i}">Refaire le clip…</button>`:''}</div>`).join('')}</div>`:''}${j.final?`<h3 style="margin-top:24px">Votre épisode est prêt</h3><video class="final-video" src="${j.final}" controls></video><div class="actions"><a class="primary" href="${j.final}" download="fruchtdrama.mp4">${ico('download')} Télécharger le MP4</a><a class="secondary" href="${j.cover}?download=1" download>${ico('download')} Couverture</a>${j.cover_file?'<button class="secondary" data-redo="cover">Refaire la couverture…</button>':''}<a class="secondary" href="/media/${j.id}/description.txt?download=1" download="description.txt">${ico('download')} Description</a><button class="secondary" data-action="copyDescription">Copier la description</button>${j.publication?`<a class="secondary" href="${j.publication}?download=1" download>${ico('download')} Kit de publication</a>`:''}<button class="secondary" data-series="1">Écrire la suite (partie ${(j.series?.part||1)+1})…</button></div><details><summary>Aperçu de la couverture et description</summary><img class="cover-preview" src="${j.cover}" alt="Couverture à télécharger"><label>Description TikTok<textarea id="finalDescription" readonly rows="5">${esc(j.script?.description||'')}</textarea></label></details><p class="hint">Sous-titres : alignement vocal lorsque le contrôle local le permet, sinon timing estimé. Vérifiez les répliques, les voix et les lèvres avant publication.</p>`:''}<div class="logs">${j.events.slice(-18).reverse().map(e=>`<p><time>${new Date(e.at).toLocaleTimeString('fr',{hour:'2-digit',minute:'2-digit'})}</time>${esc(e.text)}</p>`).join('')}</div></section>`}
const assetURL=(j,file)=>`/media/${j.id}/${file}`;
// One shared sheet for the cast (P1-2): shown once, replaceable as a whole.
const usesSheet=j=>j.character_sheet===1&&j.characters.length>1&&(!!j.character_sheet_file||!j.characters.some(c=>c.file));
function scriptReview(j){if(j.status!=='waiting_review'||!j.script)return '';const names=Object.fromEntries(j.characters.map(c=>[c.id,c.name]));return `<div class="review" id="scriptReview"><b>Relisez l’histoire avant de payer les images</b><p class="hint">Corrigez les répliques si besoin. Rien n’est généré avant votre validation.</p><div class="form-grid"><label>Titre<input data-field="title" value="${esc(j.script.title)}"></label><label>Titre de couverture<input data-field="cover_title" value="${esc(j.script.cover_title)}"></label></div><label>Description<textarea data-field="description" rows="3">${esc(j.script.description)}</textarea></label>${j.script.scenes.map((sc,i)=>`<div class="review-scene"><b>Scène ${i+1}</b><small>${esc(sc.meaning)}</small>${sc.dialogue.map(l=>`<label>${esc(names[l.speaker]||l.speaker)}<input data-scene="${i}" data-speaker="${esc(l.speaker)}" value="${esc(l.text)}"></label>`).join('')}</div>`).join('')}<div class="actions"><button class="secondary" data-action="saveScript">Enregistrer les corrections</button><button class="primary" data-action="approveScript">Valider l’histoire et lancer les images</button></div></div>`}
function reviewChanges(){const box=$('#scriptReview'),scenes=[];box.querySelectorAll('[data-scene]').forEach(input=>{const i=Number(input.dataset.scene);(scenes[i]=scenes[i]||{dialogue:[]}).dialogue.push({speaker:input.dataset.speaker,text:input.value})});const out={scenes};box.querySelectorAll('[data-field]').forEach(input=>out[input.dataset.field]=input.value);return out}
function dryRunNotice(j){const routing=j.config.clip_routing||state.settings?.clip_routing;const engine=(!routing||routing==='v09_grok_first')?'Grok (clip 1) et Flow Omni 1.2 Flash (clips 2 à la fin)':routing==='flow_grok_per_clip'?'Flow (Grok seulement après refus)':{flow:'Flow',grok:'Grok Imagine',arena:'Arena',vidogrid:'Vidogrid'}[j.config.video_engine||'flow']||'le moteur choisi';if(!j.config.dry_run)return j.stage==='clips'||['research','script','characters','images'].includes(j.stage)?`<p class="hint"><button class="secondary" data-dry-run="1">Activer l’essai à blanc des clips</button> Prépare chaque clip dans ${engine} sans l’envoyer : aucun crédit consommé.</p>`:'';return `<div class="notice dry"><b>Essai à blanc des clips · ${engine}</b><p class="hint">${j.dry_run_passed?'Essai réussi : '+engine+' est prêt (image et prompt vérifiés). Rien n’a été envoyé ni facturé.':'Les clips seront préparés dans '+engine+' puis arrêtés juste avant l’envoi. Aucun crédit consommé.'}</p><button class="primary" data-dry-run="0">Passer en production réelle</button></div>`}
// P5-08: guided account change inside the FruchtDrama window, and automatic wait for a limit renewal.
function accountNotice(j){if(j.status==='waiting_account'&&j.account_switch)return `<div class="notice human"><b>Changez de compte ${esc(j.account_switch.label||'')}</b><p class="hint">Le compte ${esc(j.account_switch.from||'précédent')} a atteint sa limite. Dans la fenêtre FruchtDrama, ouvrez l’onglet du site, déconnectez-vous, connectez-vous vous-même à <b>${esc(j.account_switch.to)}</b>, puis cliquez ci-dessous. L’identité affichée est vérifiée avant tout envoi.</p><button class="primary" data-action="accountSwitched">J’ai changé de compte</button></div>`;if(j.status==='waiting_quota'&&j.wait_until)return `<div class="notice dry"><b>Limite atteinte</b><p class="hint">Reprise automatique vers ${esc(new Date(j.wait_until*1000).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}))}. Vous pouvez aussi ajouter un compte dans Connexions.</p></div>`;return ''}
// P2-06: learned limits of ChatGPT / Claude, with a manual reset after an account change.
function quotaPanel(){const rows=state.quota_status||[];return `<section class="panel"><h2>Limites apprises</h2><p class="hint">Mesurées au moment où un service refuse (fenêtre de 6 h). Estimations, pas des chiffres officiels.</p>${rows.map(q=>`<div class="profile-card"><b>${esc(q.label)}</b><div class="code">${q.blocked?'à sa limite, reprise vers '+esc(new Date(q.retry_at*1000).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})):q.capacity==null?esc(q.used)+' en 6 h · limite pas encore mesurée':'≈ '+esc(q.remaining)+' restant(s) sur ≈ '+esc(q.capacity)}</div>${q.blocked?`<button class="secondary" data-forget-quota="${esc(q.service)}">J’ai changé de compte : oublier la limite</button>`:''}</div>`).join('')}</section>`}
// P4-1: support and data hygiene.
function supportPanel(){return `<section class="panel"><h2>Assistance et entretien</h2><p class="hint">Le rapport de panne ne contient ni jeton, ni code d’appairage, ni adresse e-mail. La purge garde une copie de sauvegarde dans data/sauvegardes.</p><div class="actions"><button class="secondary" data-support="report">Copier un rapport de panne</button><button class="secondary" data-support="purge">Nettoyer l’historique (copie gardée)</button></div><pre id="reportBox" hidden></pre></section>`}
function engineAccounts(){const rows=state.engine_accounts||[];const now=Date.now()/1000;return `<section class="panel"><h2>Comptes Grok</h2><p class="hint">Adresse seulement, jamais de mot de passe. Quand un compte atteint sa limite, le studio vous demande de vous connecter au suivant dans la fenêtre FruchtDrama.</p>${rows.map(a=>`<div class="profile-card"><b>${esc(a.label)}</b> · ${esc({grok:'Grok'}[a.engine]||a.engine)}<div class="code">${esc(a.email)} · ${a.wall&&a.wall.until>now?'limite atteinte, libre vers '+esc(new Date(a.wall.until*1000).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})):'disponible'}</div><div class="actions">${a.wall&&a.wall.until>now?`<button class="secondary" data-forget-wall="${a.id}">Oublier la limite</button>`:''}<button class="secondary" data-delete-engine-account="${a.id}">Retirer</button></div></div>`).join('')}<form id="engineAccountForm"><div class="form-grid"><label>Moteur<select name="engine"><option value="grok">Grok Imagine</option></select></label><label>Adresse du compte<input name="email" type="email" required maxlength="80" placeholder="adresse@exemple.com"></label></div><button class="secondary wide">Ajouter ce compte</button></form></section>`}
// P2-02: a login or anti-robot check needs the owner; the studio never bypasses it.
function humanNotice(j){const kind=j.status==='attention'&&j.last_error?.kind;const text={login:'Connexion requise : ouvrez l’onglet du fournisseur, connectez-vous vous-même, puis cliquez sur Reprendre.',challenge:'Vérification anti-robot affichée : résolvez-la vous-même dans l’onglet, puis cliquez sur Reprendre. FruchtDrama ne la contourne jamais.'}[kind];return text?`<div class="notice human"><b>Action de votre part requise</b><p class="hint">${text}</p></div>`:''}
function uncertainClips(j){const list=j.uncertain_clips||[];if(!list.length)return '';return `<div class="notice uncertain"><b>Envoi Flow incertain</b><p class="hint">Le clip a peut-être déjà été généré et facturé. Ouvrez le projet Flow : la passerelle récupère automatiquement un clip existant, ou importez-le ci-dessous. Confirmez seulement si aucun clip n’existe dans Flow.</p>${list.map(i=>`<button class="secondary" data-confirm-no-clip="clip:${i}">Scène ${i+1} : aucun clip dans Flow, autoriser une nouvelle génération</button>`).join('')}</div>`}
function asset(j,file,title,slot){return `<div class="asset">${file?`<img src="${assetURL(j,file)}" alt="${esc(title)}">`:`<div class="asset-placeholder">${ico('image')}</div>`}<b>${esc(title)}</b><button class="secondary" data-upload="${slot}" data-type="image">${file?'Remplacer':'Importer'}</button>${file&&!j.scenes.some(s=>s.image)?`<button class="secondary redo" data-redo="${slot}">Refaire…</button>`:''}</div>`}
let accountsTab='bridge';
// Atelier-simple « Mes comptes »: the cards first, then each setting folded with a one-line summary.
// Open folds survive the periodic re-render.
// Like the Atelier's Mes comptes: the settings are shown open; a click folds them.
const openFolds=new Set();
const fold=(key,title,summary,body)=>`<details class="panel fold" data-fold="${key}" ${openFolds.has(key)?'open':''}><summary><span class="fold-title">${title}</span><span class="fold-sum">${summary}</span><span class="fold-act">Régler</span></summary><div class="fold-body">${body}</div></details>`;
document.addEventListener('toggle',e=>{const k=e.target?.dataset?.fold;if(k)e.target.open?openFolds.add(k):openFolds.delete(k);},true);
const controlsSummary=()=>{const s=state.settings||{},l={redo:'refaits seuls',report:'signalés',none:'sans contrôle'};return 'planches : '+(l[s.board_controls]||l.none)+' · clips : '+(l[s.controls]||l.report)+(s.clip_look==='ear'?' · à l’oreille':'')+' · miniature : '+({fix:'corrigée seule',report:'signalée',none:'sans contrôle'}[s.cover_controls||'fix']);};
// Atelier-like site cards: accounts already open in Chrome, detected automatically, no password kept.
const SITE_CARDS=[['chatgpt','ChatGPT',true,'l’histoire, les personnages, les images et la couverture'],['flow','Google Flow',true,'les clips vidéo (crédits Flow)'],['tiktok','TikTok',false,'Le Filon et la recherche de vidéos'],['grok','Grok Imagine',false,'les clips, dès que Flow échoue'],['claude','Claude',false,'l’histoire, si tu préfères Claude à ChatGPT']];
const siteMissing=()=>SITE_CARDS.filter(([k,,req])=>req&&!state?.sites?.[k]?.connected).length;
function sitesPanel(){const sites=state.sites||{};const checked=Object.values(sites).map(x=>x.checked).filter(Boolean).sort().pop();const pending=sites._requested&&(!checked||sites._requested>checked);
return `<section class="site-grid">${SITE_CARDS.map(([k,name,req,role])=>{const s=sites[k];const wall=(state.quota_status||[]).filter(q=>q.blocked&&q.service.startsWith(k==='claude'?'claude':k==='chatgpt'?'chatgpt':'-')).map(q=>`<span class="dot-state warn">${esc(q.label)} à la limite · nouvel essai ${new Date(q.retry_at*1000).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}${q.announced?'':' (estimé)'}</span>`).join('');const st=wall||(!s?'<span class="dot-state idle">non vérifié</span>':s.challenge?'<span class="dot-state warn">vérification anti-robot à faire</span>':s.connected?`<span class="dot-state ok">connecté${s.email?' · '+esc(s.email):''}</span>`:'<span class="dot-state bad">non connecté</span>');return `<article class="site-card"><div class="site-head"><b>${name}</b><span class="tag">${req?'NÉCESSAIRE':'FACULTATIF'}</span></div><p>${role}</p><div class="site-foot">${st}${s?.connected?`<button class="secondary" data-switch-help="${k}">Changer de compte</button>`:`<button class="secondary" data-site-open="${k}">Se connecter</button>`}</div></article>`}).join('')}${filesCard()}</section>${switchHelp()}
<p class="hint site-note">${pending?'Vérification en cours dans la fenêtre FruchtDrama…':checked?'Vérifié le '+new Date(checked).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'})+'.':'Pas encore vérifié : clique sur Revérifier (la fenêtre FruchtDrama doit être ouverte).'} « Se connecter » ouvre le site dans un onglet de la fenêtre FruchtDrama : connecte-toi, la carte passe au vert toute seule et l’onglet se referme.</p>
`}
function settingsFolds(){return `<h2 class="section-h">Réglages</h2>`+
fold('lang','Langue des nouveaux épisodes',esc((LANGS.find(([v])=>v===state.settings.language)||[0,state.settings.language||''])[1]),`<section class="panel lang-panel"><div><h3>Langue des nouveaux épisodes</h3><p class="hint">Les épisodes créés à partir de maintenant sont écrits et parlés dans cette langue. Ceux qui existent ne bougent pas.</p></div><div class="lang-choice">${LANGS.map(([v,l])=>`<button class="${state.settings.language===v?'primary':'secondary'}" data-default-language="${v}">${l}</button>`).join('')}</div></section>`)+
fold('montage','Montage de mes vidéos',esc(state.montage_summary||''),montagePanel())+
fold('controls','Contrôles et essai à blanc',esc(controlsSummary()),controlsPanel())+
fold('backups','Mes sauvegardes',esc(((state.backups||{}).count??0)+' histoire(s) sauvegardée(s)'),backupPanel())+
fold('support','En cas de souci','rapport de panne',`<section class="panel"><p class="hint">Si quelque chose bloque, copie le rapport et colle-le dans ton message à ton formateur. Il dit ce que le studio a vu : versions, comptes, derniers échecs et journal. Ni jeton, ni code d’appairage, ni adresse e-mail.</p><div class="actions"><button class="secondary" data-support="report">Copier le rapport de panne</button></div><pre id="reportBox" hidden></pre></section>`)+
fold('theme','Apparence',esc(THEMES[themeGet()][0]+' · '+THEMES[themeGet()][2]),`<section class="panel"><p class="hint">Gardée sur cet ordinateur.</p><div class="palette-grid">${Object.entries(THEMES).map(([k,[name,,sub]])=>`<button type="button" class="palette pal-${k}${themeGet()===k?' on':''}" data-theme-pick="${k}" aria-pressed="${themeGet()===k}"><span class="swatches" aria-hidden="true"><i></i><i></i><i></i><i></i></span><b>${name}</b><small>${sub}</small></button>`).join('')}</div></section>`)}
function browserPanel(){const ext=document.documentElement.dataset.fruchtExtension,n=state.bridge_notice,jobs=state.jobs.filter(j=>j.stage==='script');
return `<section class="panel account-block browser-panel"><h2>Cette fenêtre FruchtDrama</h2><p class="hint">${ext?'Extension FruchtDrama '+esc(ext)+' active dans ce navigateur.':'Extension non détectée dans cet onglet : ouvrez le studio par l’icône FruchtDrama épinglée.'}</p>
<div class="browser-actions"><div><b>Mémoriser le compte Flow</b><small>Ouvrez d’abord, dans cette fenêtre, un projet Flow du compte voulu.</small><button class="secondary" data-bridge-action="register_flow">Mémoriser le compte Flow ouvert</button></div>
<div><b>Ranger les onglets IA</b><small>Ferme les conversations terminées ; elles restent dans l’historique.</small><button class="secondary" data-bridge-action="tidy">Ranger les onglets</button></div>
<div><b>Récupérer une réponse</b><small>Secours : lit la réponse déjà affichée dans l’onglet ChatGPT ou Claude, sans renvoyer de prompt.</small><select id="recoverJob">${jobs.map(j=>`<option value="${j.id}">${esc(j.title)} · ${esc(j.id.slice(0,6))}</option>`).join('')||'<option value="">Aucun scénario en attente</option>'}</select><button class="secondary" data-bridge-action="recover" ${jobs.length?'':'disabled'}>Récupérer</button></div></div>
${n?`<p class="bridge-notice ${n.pending?'':n.ok?'ok':'bad'}">${esc(n.text)} <time>${new Date(n.at).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}</time></p>`:''}</section>`}
const pill=(cls,text)=>`<span class="state ${cls}">${esc(text)}</span>`;
const SERVICE_NAMES={chatgpt:'ChatGPT',claude:'Claude',flow:'Google Flow',grok:'Grok'};
function keyPanel(){return `<section class="panel key-panel"><div><h3>Clé du studio</h3><p class="hint">${state.key_saved?'Enregistrée par l’extension la première fois. Elle reste cachée : rien à recopier.':'Pas encore enregistrée : cliquez sur l’icône FruchtDrama épinglée dans Chrome, elle s’enregistre seule.'}</p></div><div class="key-state">${state.key_saved?`<span class="masked-key">••••••••••••</span>${pill('ok','Enregistrée')}`:pill('idle','En attente')}<button class="secondary" data-key-reset="1">Autoriser une nouvelle extension</button></div></section>`}
function unifiedPanel(){const rows=state.accounts||[];const cell=(r,k)=>{const x=r.services[k];if(!x)return `<td><button class="link-btn" data-add-service="${esc(r.email)}" data-service="${k}">Ajouter</button></td>`;const tone={live:'ok',ok:'ok',wall:'warn',low:'warn',blocked:'bad',off:'bad'}[x.state]||'idle';return `<td>${pill(tone,x.text)}<button class="link-btn" data-remove-service="${esc(r.email)}" data-service="${k}" title="Retirer ce service">Retirer</button></td>`};
return `<details class="panel more-accounts"><summary>Autres réglages des comptes (clé, adresses, Grok)</summary>`+keyPanel()+`<section class="panel account-block"><h2>Adresses</h2><p class="hint">Une adresse, une seule fois : cochez les services qu’elle ouvre. Le studio crée lui-même le profil Flow et la rotation Grok. Aucun mot de passe.</p>
<table class="accounts unified"><thead><tr><th>Adresse</th>${Object.values(SERVICE_NAMES).map(n=>`<th>${n}</th>`).join('')}<th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.label)}</b>${r.label!==r.email?`<small>${esc(r.email)}</small>`:''}</td>${Object.keys(SERVICE_NAMES).map(k=>cell(r,k)).join('')}<td class="row-actions"><button class="secondary" data-delete-account="${esc(r.email)}">Retirer</button></td></tr>`).join('')||`<tr><td colspan="7" class="empty-row">Aucun compte. Ajoutez votre première adresse ci-dessous.</td></tr>`}</tbody></table>${rows.length?`<div class="actions"><button class="secondary danger" data-delete-all-accounts="${rows.length}">Retirer tous les comptes (${rows.length})</button></div>`:''}
<form id="accountForm" class="add-account unified-add"><label>Adresse<input name="email" type="email" required maxlength="80" placeholder="adresse@gmail.com"></label><label>Nom affiché<input name="label" maxlength="60" placeholder="facultatif"></label><fieldset class="svc-choice"><legend>Services de cette adresse</legend>${Object.entries(SERVICE_NAMES).map(([k,n])=>`<label class="check"><input type="checkbox" name="services" value="${k}" ${k!=='claude'?'checked':''}> ${n}</label>`).join('')}</fieldset><label class="flow-balance">Crédits Flow<input name="balance" type="number" min="0" max="100000" placeholder="lus plus tard"></label><button class="primary">Ajouter ce compte</button></form></section></details>`}
// Daily Flow refill: the studio notes the first spend and rereads the balance 24 h later.
function refillText(p){if(!p.refill_at)return '<small>Plein</small>';const left=p.refill_at*1000-Date.now();if(left<=0)return '<small>Relecture en cours…</small>';const h=Math.floor(left/3600000),m=Math.floor(left%3600000/60000);return `<b>dans ${h?h+' h ':''}${String(m).padStart(h?2:1,'0')} min</b><small>vers ${new Date(p.refill_at*1000).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}</small>`}
// Atelier-simple: Google accounts of this Chrome, detected with their real Flow credits.
// 0.1.90: one state per account, the same everywhere (main table, Avancé): no « Prêt » on an account without Flow access.
const flowState=(p,cost)=>p.readiness?.state==='fix'?['bad','À régler']:p.blocked==='unavailable'?['bad','Sans accès à Flow']:(p.blocked==='credits'||(p.balance||0)<=0)?['bad','Vide']:(p.balance||0)<cost?['warn','Solde bas']:!p.flow_client?['idle','À détecter']:p.auto_enabled===false?['idle','Hors rotation']:['ok','Prêt'];
function flowAccountsPanel(){const rows=state.profiles.filter(p=>p.slot!=null).sort((a,b)=>a.slot-b.slot),old=state.profiles.filter(p=>p.slot==null);const cost=Number(state.settings.flow_cost||12),n=state.bridge_notice,wins=[...new Set(rows.map(p=>p.flow_client).filter(Boolean))],auto=!!state.settings.flow_auto;
 const using=new Set(state.jobs.filter(j=>j.status!=='done'&&j.stage==='clips'&&j.flow_profile).map(j=>j.flow_profile)),usable=rows.filter(p=>flowState(p,cost)[0]==='ok').length;
 const st=p=>{const s=flowState(p,cost);return s[1]==='Prêt'&&using.has(p.id)?['ok','En cours']:s};
 return `<section class="panel account-block"><div class="section-title"><h2>Comptes Google Flow</h2><button class="primary" data-bridge-action="scan_flow">${ico('refresh')} Détecter mes comptes</button></div>
<p class="hint">${rows.length} compte(s) · <b>${rows.reduce((a,p)=>a+(p.balance||0),0)} crédits</b> · ${usable} compte(s) avec au moins ${cost} crédits pour un clip.</p>
<label class="check switch"><input id="flowAuto" type="checkbox" ${auto?'checked':''}> Changement de compte automatique<span class="hint">${auto?'quand un compte est vide ou sans accès à Flow, le clip suivant part tout de suite sur le compte suivant, sans clic':'désactivé : quand le compte choisi est vide, l’épisode attend que tu en choisisses un autre'}</span></label>
<details class="how"><summary>Ajouter un compte Google</summary><ol class="hint"><li>Dans la fenêtre FruchtDrama : photo de profil en haut à droite › Ajouter un compte.</li><li>Clique « Détecter mes comptes » : le studio lit l’adresse et les crédits réels.</li></ol><p class="hint">Les crédits sont relus à chaque ouverture de la fenêtre, et 24 h après la première dépense (recharge quotidienne).</p></details>
${n&&n.action==='scan_flow'?`<p class="bridge-notice ${n.pending?'':n.ok?'ok':'bad'}">${esc(n.text)}<time>${n.at?esc(new Date(n.at).toLocaleString('fr-FR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})):''}</time></p>`:''}
<table class="accounts"><thead><tr><th>Compte Google</th><th>Crédits</th><th>État</th><th>Crédits de retour</th></tr></thead><tbody>${rows.map(p=>{const [t,l]=st(p);return `<tr><td><b>${esc(p.flow_email||p.label)}</b>${p.slot!=null?`<small>${wins.length>1?`fenêtre ${wins.indexOf(p.flow_client)+1} · `:''}compte n° ${p.slot}</small>`:''}</td><td class="num">${p.balance}</td><td>${pill(t,l)}</td><td>${refillText(p)}</td></tr>`}).join('')||'<tr><td colspan="4" class="empty-row">Aucun compte : clique « Détecter mes comptes ».</td></tr>'}</tbody></table>${old.length?`<p class="hint">${old.length} ancien(s) compte(s) non retrouvé(s) dans cette fenêtre : connecte-les à Chrome puis Détecter, ou retire-les dans Réglages › Avancé. Ils ne sont pas utilisés.</p>`:''}</section>`}
function windowState(){const wins=Object.values(state.clients||{}).filter(c=>c.role!=='creation'),live=wins.filter(c=>!c.disabled&&Date.now()-Date.parse(c.seen)<ONLINE_MS);
 if(live.length)return `<p class="window-state ok">${pill('ok','Fenêtre FruchtDrama en ligne')} les tâches partent toutes seules, sans fenêtre au premier plan.</p>`;
 const last=wins.map(c=>c.seen).filter(Boolean).sort().pop();
 return `<p class="window-state">${pill('bad','Aucune fenêtre FruchtDrama ouverte')} ${last?'dernier contact '+new Date(last).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'})+' · ':''}clique l’icône FruchtDrama épinglée dans Chrome : les tâches en attente repartent seules.</p>`}
function connections(){const now=Date.now()/1000,online=c=>!c.disabled&&Date.now()-Date.parse(c.seen)<ONLINE_MS,clients=Object.values(state.clients),flowTotal=state.profiles.reduce((a,p)=>a+(p.balance||0),0),eng=state.engine_accounts||[],quota=(state.quota_status||[]);
const status=(cls,text)=>`<span class="state ${cls}">${esc(text)}</span>`;
const flowRow=p=>`<tr><td><b>${esc(p.label)}</b><small>${p.flow_url?'Session mémorisée':'Session à mémoriser depuis la passerelle'}</small></td><td class="num">${esc(p.balance)}<small>${p.credit_source==='flow'?'lu dans Flow':'déclaré'}${p.checked?' · '+new Date(p.checked).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'}):''}</small></td><td>${!p.flow_url?status('warn','À mémoriser'):status(...flowState(p,Number(state.settings.flow_cost||12)))}${p.credit_error?`<small>${esc(p.credit_error)}</small>`:''}</td><td class="row-actions">${p.flow_url?`<button class="secondary" data-check-credits="${p.id}">${ico('refresh')} Vérifier</button>`:''}<details class="row-more"><summary>Réglages</summary><label>Crédits disponibles<input type="number" id="balance-${p.id}" value="${p.balance}" min="0" max="100000"></label>${p.flow_url?`<label class="check"><input id="auto-${p.id}" type="checkbox" ${p.auto_enabled?'checked':''}> Inclure dans le passage automatique</label><label>Profil Chrome (facultatif)<input id="chrome-${p.id}" value="${esc(p.chrome_profile||'')}" placeholder="Default, Profile 1…"></label>`:''}<div class="code">Identifiant : ${p.id}</div><div class="actions"><button class="secondary" data-balance="${p.id}">Enregistrer</button><button class="secondary danger" data-delete-profile="${p.id}">Retirer</button></div></details></td></tr>`;
const engineRows=engine=>{const rows=eng.filter(a=>a.engine===engine);return rows.length?rows.map(a=>{const walled=a.wall&&a.wall.until>now;return `<tr><td><b>${esc(a.email)}</b><small>${esc(a.label!==a.email?a.label:'')}</small></td><td class="num">—<small>pas de solde affiché</small></td><td>${walled?status('bad','Limite atteinte · libre vers '+new Date(a.wall.until*1000).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})):status('ok','Disponible')}</td><td class="row-actions">${walled?`<button class="secondary" data-forget-wall="${a.id}">Oublier la limite</button>`:''}<button class="secondary danger" data-delete-engine-account="${a.id}">Retirer</button></td></tr>`}).join(''):`<tr><td colspan="4" class="empty-row">Aucun compte. Ajoutez-en un ci-dessous.</td></tr>`};
const table=(title,sub,rows,extra='')=>`<section class="panel account-block"><div class="block-head"><div><h2>${title}</h2><p class="hint">${sub}</p></div>${extra}</div><table class="accounts"><thead><tr><th>Compte</th><th>Crédits</th><th>État</th><th></th></tr></thead><tbody>${rows}</tbody></table></section>`;
const addForm=e=>`<div class="add-inline"><h3>Ajouter un compte ${{flow:"Google Flow",grok:"Grok"}[e]}</h3><p class="hint">Adresse seulement, jamais de mot de passe. Connectez-vous ensuite vous-même au site, dans la fenêtre FruchtDrama.</p><form id="engineAccountForm" class="add-account"><label>Plateforme<select name="engine"><option value="flow" ${e==="flow"?"selected":""}>Google Flow</option><option value="grok" ${e==="grok"?"selected":""}>Grok Imagine</option></select></label><label>Adresse du compte<input name="email" type="email" required maxlength="80" placeholder="adresse@exemple.com"></label><label class="flow-balance" ${e!=="flow"?"hidden":""}>Crédits disponibles<input name="balance" type="number" value="50" min="0" max="100000"></label><button class="primary">Ajouter</button></form></div>`;
const panes0={flow:table('Google Flow','Crédits par compte. Quand un compte est épuisé, le studio passe au suivant dans la fenêtre FruchtDrama.',state.profiles.map(flowRow).join('')||`<tr><td colspan="4" class="empty-row">Aucun compte Flow.</td></tr>`,`<p class="hint">Changement de compte automatique : ${state.settings.flow_auto?'activé':'désactivé'} (réglé dans « Comptes Google Flow », en haut de Mes comptes).</p>`)+'',grok:table('Grok Imagine','Pas de solde lisible : la limite de chaque compte est apprise au premier refus.',engineRows('grok')),ia:`<section class="panel account-block"><h2>ChatGPT et Claude</h2><p class="hint">Limites mesurées au moment où le service refuse (fenêtre de 6 h). Estimations, pas des chiffres officiels.</p><table class="accounts"><thead><tr><th>Service</th><th>Utilisé (6 h)</th><th>État</th><th></th></tr></thead><tbody>${quota.map(q=>`<tr><td><b>${esc(q.label)}</b></td><td class="num">${esc(q.used)}<small>${q.capacity==null?'limite non mesurée':'≈ '+esc(q.remaining)+' restant(s) sur ≈ '+esc(q.capacity)}</small></td><td>${q.blocked?status('bad','Limite · reprise '+new Date(q.retry_at*1000).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})):status('ok','Disponible')}</td><td class="row-actions">${q.blocked?`<button class="secondary" data-forget-quota="${esc(q.service)}">J’ai changé de compte</button>`:''}</td></tr>`).join('')}</tbody></table></section>`,bridge:browserPanel()+`<section class="panel account-block"><h2>Navigateurs reliés</h2><p class="hint">Tout se règle ici, dans le studio : l’extension n’a plus de page à elle.</p><details class="manual-pair"><summary>Appairage manuel (secours, autre ordinateur)</summary><div class="pair-row"><div class="big-code">${esc(state.pair_code)}</div><button class="secondary" data-action="copyCode">Copier le code</button></div></details><table class="accounts"><thead><tr><th>Navigateur</th><th>Rôle</th><th>État</th><th>Dernier contact</th></tr></thead><tbody>${clients.map(c=>`<tr><td><b>${esc(c.label)}</b></td><td>${esc({all:'Recherche, IA et vidéo',creation:'Recherche et IA',flow:'Vidéo uniquement'}[c.role]||c.role)}<small>IA : ${esc(c.ai_provider||'both')}</small></td><td>${c.disabled?status('warn','Désactivée'):online(c)?status('ok','En ligne'):status('idle','Hors ligne')}</td><td>${new Date(c.seen).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'})}<button class="secondary" data-client-toggle="${c.id}" data-off="${c.disabled?0:1}">${c.disabled?'Réactiver':'Désactiver'}</button>${online(c)?'':`<button class="secondary" data-client-forget="${c.id}">Oublier</button>`}</td></tr>`).join('')||`<tr><td colspan="4" class="empty-row">Aucune passerelle appairée.</td></tr>`}</tbody></table></section>`,support:`${supportPanel()}<section class="panel"><h3>Environnement</h3><p class="hint">ffmpeg : <b>${state.ffmpeg?'détecté':'non détecté — requis pour exporter'}</b> · version ${esc(state.version||'')} · données dans le dossier local « data ». Aucune publication automatique.</p></section>`};
const panes={bridge:panes0.bridge,limits:panes0.flow+panes0.grok+panes0.ia,support:panes0.support};const tabs=[['bridge','Navigateur',clients.filter(online).length+'/'+clients.length],['limits','Crédits et limites',''],['support','Assistance','']];if(!panes[accountsTab])accountsTab='bridge';
return accountsHome()+settingsFolds()+
fold('advanced','Avancé','détails techniques : sessions, tableau Flow, navigateurs, clé, limites, assistance',windowState()+`<div class="actions"><button class="secondary" data-sites-check="1">${ico('refresh')} Revérifier les sessions</button></div>`+sitesPanel()+flowAccountsPanel()+unifiedPanel()+`<div class="tabs" role="tablist">${tabs.map(([k,l,n])=>`<button role="tab" class="tab ${accountsTab===k?'active':''}" data-account-tab="${k}">${l}${n!==''?`<span>${n}</span>`:''}</button>`).join('')}</div><div class="tab-pane">${panes[accountsTab]}</div>`)}
function guide(){return intro('Votre premier épisode.','Un démarrage simple, puis une production suivie étape par étape.',false)+`<section class="panel"><h2>Installation en quatre étapes</h2><ol class="hint" style="line-height:2.5"><li>Ajoutez un profil Flow dans Connexions et vérifiez son solde.</li><li>Dans Chrome, chargez le dossier extension en mode développeur, puis cliquez sur son icône : la fenêtre FruchtDrama s’ouvre et tout s’y passe. L’extension s’appaire seule : rien à copier.</li><li>Connectez-vous vous-même à ChatGPT ou Claude, TikTok et Flow. Dans l’extension, sélectionnez le profil Flow correspondant.</li><li>Créez un épisode. Laissez le studio et le navigateur actifs. Le premier essai sert à valider vos connecteurs.</li></ol><h3 style="margin-top:25px">Si un connecteur bloque</h3><p class="hint">Le studio passe en « À vérifier ». Le journal précise l’étape. Vous pouvez copier le prompt, générer le média vous-même puis l’importer au bon emplacement. Ne relancez pas un clip avant d’avoir vérifié s’il existe déjà dans Flow : une seconde génération peut coûter des crédits.</p><h3 style="margin-top:25px">Recherche et originalité</h3><p class="hint">La recherche est obligatoire. Le studio conserve les liens et la base du classement ; il n’invente pas les données manquantes et ne prétend pas connaître la répartition géographique des spectateurs. Le scénario doit être original, les références servent à identifier les thèmes et mécanismes narratifs.</p><h3 style="margin-top:25px">Votre budget gratuit</h3><p class="hint">Exemple Omni 720p : quatre clips de huit secondes à douze crédits coûtent quarante-huit crédits. Deux crédits restent si votre solde réel est cinquante, ce qui ne suffit pas à une nouvelle génération. Le studio réserve le coût au démarrage ; après un échec, vérifiez le solde réel. Le renouvellement des crédits reste à vérifier. Le passage au compte suivant fonctionne seulement pour les sessions Flow mémorisées et autorisées.</p><h3 style="margin-top:25px">Contrôle avant publication</h3><p class="hint">Le montage est automatique. Les sous-titres karaoké suivent la transcription quand elle est fiable, sinon un timing estimé. La production continue seule seulement si les paroles correspondent à 85 % au moins, sans défaut technique ni réserve visuelle. Regardez le MP4, vérifiez les voix et les lèvres.</p></section>
<section class="panel guide-new"><h2>Nouveautés de la version ${esc(state.version||'')}</h2><div class="guide-grid">
<div><h3>Fenêtre FruchtDrama</h3><p class="hint">Un clic sur l’icône de l’extension ouvre une fenêtre dédiée : studio, ChatGPT, Claude, TikTok, Flow, Grok et Arena s’y ouvrent, comptes compris.</p></div>
<div><h3>Moteur V09</h3><p class="hint">Clip 1 sur Grok Imagine (10 s), Flow s’il n’est pas disponible ; clips 2 à la fin sur Google Flow, Omni 1.2 Flash, 10 s (30 crédits). Commencez par un essai à blanc.</p></div>
<div><h3>Changement de compte</h3><p class="hint">Flow passe seul au compte suivant. Pour Grok et Arena, le studio vous indique le compte à connecter puis vérifie l’identité avant d’envoyer.</p></div>
<div><h3>Limites et refus</h3><p class="hint">Une limite atteinte met la production en attente puis la relance seule. Une image refusée par ChatGPT est reformulée deux fois, même style.</p></div>
<div><h3>File de nuit</h3><p class="hint">Ajoutez des productions puis démarrez la file : une à la fois, erreurs techniques relancées, PC maintenu éveillé (Windows).</p></div>
<div><h3>Corriger sans tout refaire</h3><p class="hint">Relecture de l’histoire avant les images, « Refaire » d’un média avec une consigne, essai à blanc, une seule feuille de personnages.</p></div>
<div><h3>Séries et publication</h3><p class="hint">« Écrire la suite » réutilise les personnages déjà payés. Le kit de publication donne titre, description, hashtags et créneaux.</p></div>
<div><h3>Assistance</h3><p class="hint">Mes comptes, rubrique Assistance : rapport de panne sans secret, nettoyage avec copie de sauvegarde, suppression vers la corbeille.</p></div>
</div><p class="hint">Mode d’emploi complet : docs/MODE-EMPLOI.md.</p></section>`}
function render(){if(!state)return;document.querySelectorAll('nav button,header [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#breadcrumb').innerHTML=`Espace de travail / <b>${({filon:'Le Filon',studio:'Studio',library:'Bibliothèque',connections:'Mes comptes',guide:'Mode d’emploi'})[page]}</b>`;{const sub=document.querySelector('nav [data-page="connections"] small');if(sub)sub.textContent=accountsSummary();}paintIcons();$('#content').innerHTML=page==='filon'?filon():page==='studio'?studio():page==='connections'?connections():page==='guide'?guide():intro('Votre bibliothèque.','Les épisodes et leurs fichiers, réunis au même endroit.')+`<section class="panel">${list()}</section>`+(selected?detail():'');}
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-page]');if(!el)return;try{if(el.dataset.page){if(reviewDirty&&!window.confirm('Des corrections de l’histoire ne sont pas enregistrées. Les abandonner ?'))return;reviewDirty=false;page=el.dataset.page;render();return}if(el.dataset.job){if(reviewDirty&&!window.confirm('Des corrections de l’histoire ne sont pas enregistrées. Les abandonner ?'))return;reviewDirty=false;selected=el.dataset.job;render();setTimeout(()=>$('.detail')?.scrollIntoView({behavior:'smooth',block:'start'}),50);return}const action=el.dataset.action;if(action==='new'){openCreate(el.dataset.source||'');return}if(action==='copyDescription'){const text=state.jobs.find(j=>j.id===selected)?.script?.description;if(!text)throw Error('Description indisponible');try{await navigator.clipboard.writeText(text);toast('Description copiée')}catch{const box=$('#finalDescription');box.closest('details').open=true;box.focus();box.select();toast('Texte sélectionné : appuyez sur Ctrl+C pour le copier')}return}if(action==='copyCode'){await navigator.clipboard.writeText(state.pair_code);toast('Code copié')}if(el.dataset.command){const cj=state.jobs.find(x=>x.id===selected);if(el.dataset.command==='resume'&&cj&&typeof confirmCost==='function'&&!confirmCost(cj,'Fabriquer'))return;await api('/api/job/'+selected,{action:el.dataset.command,flow_profile:$('#jobProfile')?.value});await refresh(true)}if(el.dataset.source){await api('/api/job/'+selected,{action:'select',url:el.dataset.source});await refresh(true)}if(action==='research'){const rows=$('#researchInput').value.split('\n').filter(Boolean).map(l=>{const [url,n]=l.split('|');return {url:url.trim(),views:n?.trim()?Number(n.trim().replace(/\s/g,'')):null,title:'Référence ajoutée par le propriétaire'}});await api('/api/job/'+selected,{action:'research',candidates:rows});await refresh(true)}if(action==='script'){await api('/api/job/'+selected,{action:'script',script:JSON.parse($('#scriptInput').value)});await refresh(true)}if(el.dataset.copyTask){const t=state.tasks.find(t=>t.id===el.dataset.copyTask);await navigator.clipboard.writeText(t.payload.prompt||t.payload.query);toast('Prompt copié')}if(el.dataset.upload){uploadSlot={job:selected,slot:el.dataset.upload};$('#fileInput').accept=el.dataset.type==='video'?'video/mp4,video/webm':'image/png,image/jpeg,image/webp';$('#fileInput').value='';$('#fileInput').click()}if(action==='saveScript'){await api('/api/job/'+selected,{action:'edit_script',script:reviewChanges()});reviewDirty=false;await refresh(true);toast('Corrections enregistrées');return}if(action==='approveScript'){await api('/api/job/'+selected,{action:'edit_script',script:reviewChanges()});await api('/api/job/'+selected,{action:'approve_script'});reviewDirty=false;await refresh(true);toast('Histoire validée : images lancées');return}if(el.dataset.redo){const slot=el.dataset.redo,isClip=slot.startsWith('clip:'),withClip=el.dataset.hasClip==='1';const what=slot==='cover'?'la couverture':slot.startsWith('image:')?'l’image de la scène '+(Number(slot.split(':')[1])+1):isClip?'le clip de la scène '+(Number(slot.split(':')[1])+1):slot.startsWith('state:')?'la feuille d’état':'les personnages';const rj=state.jobs.find(x=>x.id===selected),clipPrice=rj&&typeof clipCost==='function'?clipCost(rj,1):'1 clip';if(withClip&&!window.confirm('Le clip de cette scène a été animé depuis cette image : il faut refaire l’image ET le clip.\n\nCoût : 1 image ChatGPT · '+clipPrice+'. Les versions actuelles sont gardées (« Remettre »). Continuer ?'))return;if(isClip&&!window.confirm('Refaire '+what+' ?\n\nCoût : '+clipPrice+'. L’ancienne version est gardée : « Remettre » la rend. Continuer ?'))return;const note=window.prompt('Refaire '+what+'. Correction à appliquer (facultatif) :','');if(note===null)return;await api('/api/job/'+selected,{action:'redo',slot,note,include_clip:withClip});await refresh(true);toast('Nouvelle tentative programmée ; le fichier précédent est conservé.');return}if(el.dataset.dryRun){const enabled=el.dataset.dryRun==='1';if(!enabled&&!window.confirm('Les prochains clips seront envoyés à Flow et consommeront des crédits. Continuer ?'))return;await api('/api/job/'+selected,{action:'set_dry_run',enabled});if(!enabled)await api('/api/job/'+selected,{action:'resume',flow_profile:$('#jobProfile')?.value});await refresh(true);toast(enabled?'Essai à blanc activé':'Production réelle lancée');return}if(el.dataset.action==='accountSwitched'){await api('/api/job/'+selected,{action:'account_switched'});await refresh(true);toast('Changement de compte confirmé');return}if(el.dataset.series){const note=window.prompt('Suite de l’épisode : une idée pour la partie suivante ? (facultatif)','');if(note===null)return;const r=await api('/api/job/'+selected,{action:'continue_series',note});selected=r.created;await refresh(true);toast('Partie suivante créée : mêmes personnages, scénario en cours');return}if(el.dataset.deleteJob){if(!window.confirm('Supprimer cette production du studio ? Son dossier est déplacé dans data/corbeille (récupérable).'))return;const r=await api('/api/job/'+selected,{action:'delete'});selected=null;await refresh(true);toast('Production déplacée dans la corbeille : '+r.trashed);return}if(el.dataset.support==='report'){const r=await fetch('/api/report');const text=await r.text();const box=$('#reportBox');box.textContent=text;box.hidden=false;try{await navigator.clipboard.writeText(text);toast('Rapport copié')}catch{toast('Rapport affiché ci-dessous : sélectionnez-le pour le copier')}return}if(el.dataset.support==='purge'){const r=await api('/api/maintenance/purge',{});await refresh(true);toast('Nettoyage : '+r.purge.tasks_removed+' tâche(s), '+r.purge.events_removed+' événement(s) ; copie gardée');return}if(el.dataset.night){const action=el.dataset.night;await api('/api/night',{action,job:['add','remove'].includes(action)?selected:undefined});await refresh(true);toast({add:'Ajoutée à la file de nuit',remove:'Retirée de la file de nuit',start:'File de nuit démarrée',stop:'File de nuit arrêtée'}[action]);return}if(el.dataset.sitesCheck){await api('/api/sites',{action:'check'});await refresh(true);toast('Vérification lancée dans la fenêtre FruchtDrama');return}if(el.dataset.siteOpen){await api('/api/sites',{action:'open',site:el.dataset.siteOpen});toast('Ouverture du site dans la fenêtre FruchtDrama : connecte-toi, puis Revérifier');return}if(el.dataset.themePick){themeSet(el.dataset.themePick);applyTheme();render();return}if(el.dataset.controls){await api('/api/settings',{controls:el.dataset.controls});await refresh(true);toast({redo:'Clips signalés refaits automatiquement une fois',report:'Clips signalés : tu décides',none:'Contrôles désactivés pour les nouveaux épisodes'}[el.dataset.controls]);return}if(el.dataset.defaultLanguage){await api('/api/settings',{language:el.dataset.defaultLanguage});await refresh(true);toast('Langue des nouveaux épisodes enregistrée');return}if(el.dataset.clientForget){if(!window.confirm('Oublier ce navigateur hors ligne ? Il devra s’appairer à nouveau.'))return;await api('/api/client',{id:el.dataset.clientForget,forget:true});await refresh(true);toast('Navigateur oublié');return}if(el.dataset.clientToggle){await api('/api/client',{id:el.dataset.clientToggle,disabled:el.dataset.off==='1'});await refresh(true);toast(el.dataset.off==='1'?'Passerelle désactivée : elle ne reçoit plus de tâches':'Passerelle réactivée');return}if(el.dataset.bridgeAction){const action=el.dataset.bridgeAction;await api('/api/sites',{action,job:action==='recover'?$('#recoverJob').value:undefined});await refresh(true);toast('Demande envoyée à la fenêtre FruchtDrama');return}if(el.dataset.keyReset){if(!window.confirm('Autoriser la prochaine extension FruchtDrama qui s’ouvrira à s’appairer seule ? À utiliser après une réinstallation.'))return;await api('/api/key/reset',{});await refresh(true);toast('Cliquez maintenant sur l’icône de la nouvelle extension');return}if(el.dataset.addService){const svc=el.dataset.service;let balance=0;if(svc==='flow'){const v=window.prompt('Crédits Flow de ce compte (laisser vide si inconnu) :','');if(v===null)return;balance=Number(v||0)}await api('/api/account',{email:el.dataset.addService,services:[svc],balance});await refresh(true);toast(SERVICE_NAMES[svc]+' ajouté à ce compte');return}if(el.dataset.removeService){if(!window.confirm('Retirer '+SERVICE_NAMES[el.dataset.service]+' de '+el.dataset.removeService+' ?'))return;await api('/api/account',{email:el.dataset.removeService,remove_service:el.dataset.service});await refresh(true);return}if(el.dataset.deleteAllAccounts){if(!window.confirm('Retirer les '+el.dataset.deleteAllAccounts+' comptes du studio (adresses, profils Flow, comptes Grok) ? Les vidéos sont conservées et une sauvegarde est faite avant.'))return;if(window.prompt('Pour confirmer, tapez RETIRER','')!=='RETIRER'){toast('Annulé : aucun compte retiré');return}const r=await api('/api/account',{delete_all:true});await refresh(true);toast(r.removed+' compte(s) retiré(s)'+(r.kept.length?' ; gardé(s) car un clip est en cours : '+r.kept.join(', '):'')+'. Sauvegarde : '+r.backup);return}if(el.dataset.deleteAccount){if(!window.confirm('Retirer '+el.dataset.deleteAccount+' et tous ses services du studio ? Les vidéos sont conservées.'))return;await api('/api/account',{email:el.dataset.deleteAccount,delete:true});await refresh(true);toast('Compte retiré');return}if(el.dataset.accountTab){accountsTab=el.dataset.accountTab;render();return}if(el.dataset.forgetQuota){await api('/api/quota/forget',{service:el.dataset.forgetQuota});await refresh(true);toast('Limite oubliée');return}if(el.dataset.forgetWall){await api('/api/engine-account',{id:el.dataset.forgetWall,forget_wall:true});await refresh(true);toast('Limite oubliée');return}if(el.dataset.deleteEngineAccount){if(!window.confirm('Retirer ce compte du studio ?'))return;await api('/api/engine-account',{id:el.dataset.deleteEngineAccount,delete:true});await refresh(true);return}if(el.dataset.confirmNoClip){const slot=el.dataset.confirmNoClip,n=Number(slot.split(':')[1])+1;if(!window.confirm('Confirmez-vous qu’aucun clip de la scène '+n+' n’existe dans Flow ? Une nouvelle génération consommera des crédits.'))return;await api('/api/job/'+selected,{action:'confirm_no_clip',slot});await refresh(true);toast('Confirmation enregistrée. Cliquez sur Reprendre pour relancer la scène.');return}if(el.dataset.checkCredits){await api('/api/profile/check',{id:el.dataset.checkCredits});toast('Lecture du solde réel demandée à la passerelle Flow');await refresh(true);return}if(el.dataset.deleteProfile){const id=el.dataset.deleteProfile,p=state.profiles.find(p=>p.id===id);if(!p)return;if(!window.confirm('Supprimer le profil « '+p.label+' » de l’application ? Les vidéos et le compte Google seront conservés.'))return;await api('/api/profile/delete',{id});await refresh(true);toast('Profil supprimé. Les productions et les vidéos sont conservées.');return}if(el.dataset.balance){const id=el.dataset.balance,p=state.profiles.find(p=>p.id===id);await api('/api/profile',{id,label:p.label,balance:Number($('#balance-'+id).value),...(p.flow_url?{auto_enabled:$('#auto-'+id).checked,chrome_profile:$('#chrome-'+id).value}:{})});await refresh(true)}}catch(err){toast(err.message)}});
document.addEventListener('input',e=>{if(e.target.closest?.('#scriptReview'))reviewDirty=true;if(e.target.name==='language'){const queries={'Deutsch (de-DE)':'KI Früchte Geschichten deutsch','Français (fr-FR)':'histoires fruits IA français','English (en-US)':'AI fruit drama stories English','Español (es-ES)':'historias de frutas IA español','Português (pt-BR)':'histórias de frutas IA português'};document.querySelector('[name=query]').value=queries[e.target.value]||queries['Deutsch (de-DE)'];}});
document.addEventListener('change',async e=>{if(e.target.id==='flowAuto'){try{await api('/api/flow-auto',{enabled:e.target.checked});await refresh(true);toast(e.target.checked?'Passage automatique activé':'Passage automatique désactivé')}catch(err){toast(err.message)}}if(e.target.id==='jobProvider'){try{await api('/api/job/'+selected,{action:'provider',provider:e.target.value});toast('IA modifiée pour les prochaines tâches de scénario');await refresh(true)}catch(err){toast(err.message)}}});
document.addEventListener('submit',async e=>{if(e.target.id==='createForm'){e.preventDefault();const f=new FormData(e.target);try{await api('/api/job',{brief:String(f.get('brief')||'').trim()||'Choisis le sujet après la recherche des références. Invente une histoire originale adaptée à la référence retenue, sans en copier les dialogues ou les plans.',flow_profile:f.get('flow_profile'),source_url:String(f.get('source_url')||'').trim(),config:{provider:f.get('provider'),scene_count:Number(f.get('scene_count')),query:f.get('query'),language:f.get('language'),flow_cost:Number(f.get('flow_cost')),flow_model:f.get('flow_model'),video_engine:f.get('video_engine')||'flow',review_script:f.get('review_script')==='on',dry_run:f.get('dry_run')==='on',karaoke:f.get('karaoke')==='on'}});$('#createDialog').close();await refresh();selected=state.jobs[0].id;page='studio';render();toast('Production créée : recherche en attente du connecteur')}catch(err){toast(err.message)}}if(e.target.id==='accountForm'){e.preventDefault();const f=new FormData(e.target);try{await api('/api/account',{email:f.get('email'),label:f.get('label'),services:f.getAll('services'),balance:Number(f.get('balance')||0)});await refresh(true);toast('Compte ajouté pour tous les services cochés')}catch(err){toast(err.message)}}if(e.target.id==='engineAccountForm'){e.preventDefault();const f=new FormData(e.target);try{if(f.get('engine')==='flow')await api('/api/profile',{label:f.get('email'),balance:Number(f.get('balance')||0)});else await api('/api/engine-account',{engine:f.get('engine'),email:f.get('email'),label:f.get('email')});await refresh(true);toast('Compte ajouté')}catch(err){toast(err.message)}}if(e.target.id==='profileForm'){e.preventDefault();const f=new FormData(e.target);try{await api('/api/profile',{label:f.get('label'),balance:Number(f.get('balance'))});await refresh(true)}catch(err){toast(err.message)}}});
$('#fileInput').addEventListener('change',async e=>{const file=e.target.files[0];if(!file||!uploadSlot)return;try{toast('Import en cours…');const ext=file.name.split('.').pop().toLowerCase();const r=await fetch(`/api/upload?job=${uploadSlot.job}&slot=${encodeURIComponent(uploadSlot.slot)}&ext=${ext}`,{method:'POST',body:file});const b=await r.json();if(!r.ok)throw Error(b.error);await refresh(true);toast('Média importé, progression enregistrée')}catch(err){toast(err.message)}});
window.addEventListener('hashchange',()=>{const job=new URLSearchParams(location.hash.slice(1)).get('job');if(!job||job===selected)return;if(reviewDirty&&!window.confirm('Des corrections de l’histoire ne sont pas enregistrées. Les abandonner ?'))return;reviewDirty=false;selected=job;page='studio';render();});
$('#refresh').onclick=()=>refresh(true);refresh();setInterval(()=>refresh(),4000);

document.addEventListener('change',e=>{if(e.target.matches('#createForm [name=video_engine]')){const flow=e.target.value==='flow';document.querySelectorAll('#createForm .flow-only').forEach(x=>x.hidden=!flow)}if(e.target.matches('#createForm [name=flow_model]'))$('#createForm [name=flow_cost]').value=({gemini_omni_flash:12,veo_3_1_lite:10,veo_3_1_fast:20,veo_3_1_quality:100}[e.target.value]||12);});

// Click any production image to see it full screen.
document.addEventListener('click',e=>{const img=e.target.closest?.('.asset img,.cover-preview,.cast-more img');if(!img)return;let box=$('#lightbox');if(!box){box=document.createElement('dialog');box.id='lightbox';box.addEventListener('click',()=>box.close());document.body.append(box);}box.innerHTML=`<img src="${img.src}" alt="${esc(img.alt)}">`;box.showModal();});

// Light theme by default (owner choice), dark theme on demand; remembered on this computer.
// Themes like the Atelier: light by default; dark-based palettes also set the dark class.
// Seven palettes named like the Atelier: [name, dark, subtitle]. Papier is the light one (default, owner choice).
const THEMES={ardoise:['Ardoise',true,'gris ardoise et violet'],laiton:['Laiton',true,'gris neutre et laiton'],lagon:['Lagon',true,'ardoise bleutée, turquoise'],cinema:['Cinéma',true,'salle obscure et or'],papier:['Papier',false,'clair, encre et terre'],verre:['Verre',true,'nuit, menthe et bleu'],editorial:['Éditorial',true,'magazine, filets fins et orange']};
// Old names (Clair, Sombre) move to their palette; the browser may refuse storage (private window): never fatal.
const THEME_MOVED={light:'papier',dark:'ardoise'},THEME_DEFAULT='papier';
const themeSet=k=>{try{localStorage.setItem('frucht-theme',k)}catch{}};
const themeGet=()=>{let v=null;try{v=localStorage.getItem('frucht-theme')}catch{}if(THEME_MOVED[v]){v=THEME_MOVED[v];themeSet(v);}return THEMES[v]?v:THEME_DEFAULT;};
const applyTheme=()=>{const t=themeGet();document.body.classList.toggle('dark',THEMES[t][1]);Object.keys(THEMES).forEach(k=>document.body.classList.toggle('theme-'+k,k===t));};applyTheme();$('#theme').onclick=()=>{themeSet(THEMES[themeGet()][1]?'papier':'ardoise');applyTheme();render();};

paintIcons();
document.addEventListener('change',e=>{if(e.target.matches('#engineAccountForm [name=engine]'))document.querySelector('#engineAccountForm .flow-balance').hidden=e.target.value!=='flow';});

// Filon interactions: drag a card onto the creation zone, paste a TikTok link anywhere, copy links.
const tiktokLink=t=>{const m=String(t||'').match(/https:\/\/(?:www\.|vm\.|m\.)?tiktok\.com\/[^\s"'<>]+/);return m?m[0]:null;};
let openCreate=url=>{$('#createProfile').innerHTML=profileOptions(state.profiles[0]?.id);$('#createForm [name=source_url]').value=url||'';$('#createDialog').showModal();};
document.addEventListener('mouseover',e=>{const m=e.target.closest?.('.filon-media[data-video]');if(m&&m.dataset.video&&!m.closest('.filon-card.rich')&&!m.querySelector('iframe'))m.insertAdjacentHTML('afterbegin',player(m.dataset.video));});
document.addEventListener('dragstart',e=>{const card=e.target.closest?.('.filon-card');if(!card)return;e.dataTransfer.setData('text/uri-list',card.dataset.url);e.dataTransfer.setData('text/plain',card.dataset.url);card.classList.add('dragging');document.querySelector('.dropzone')?.classList.add('ready');});
document.addEventListener('dragend',e=>{e.target.closest?.('.filon-card')?.classList.remove('dragging');document.querySelector('.dropzone')?.classList.remove('ready','over');});
document.addEventListener('dragover',e=>{const z=e.target.closest?.('[data-drop]');if(z){e.preventDefault();z.classList.add('over');}});
document.addEventListener('dragleave',e=>{e.target.closest?.('[data-drop]')?.classList.remove('over');});
document.addEventListener('drop',e=>{const z=e.target.closest?.('[data-drop]');if(!z)return;e.preventDefault();z.classList.remove('over','ready');const url=tiktokLink(e.dataTransfer.getData('text/uri-list')||e.dataTransfer.getData('text/plain'));url?openCreate(url):toast('Dépose une vidéo TikTok du Filon ou un lien TikTok.');});
document.addEventListener('paste',e=>{if(e.target.closest?.('input,textarea,[contenteditable="true"]'))return;const url=tiktokLink(e.clipboardData?.getData('text'));if(url){e.preventDefault();openCreate(url);toast('Lien TikTok collé : création prête');}});
document.addEventListener('click',async e=>{const b=e.target.closest?.('[data-copy],[data-filon-refresh]');if(!b)return;try{if(b.dataset.copy){await navigator.clipboard.writeText(b.dataset.copy).catch(()=>{});toast('Lien copié');}else{await api('/api/filon',{refresh:true,niche:typeof curNiche==='function'?curNiche():undefined});await refresh(true);toast('Actualisation du Filon lancée');}}catch(err){toast(err.message)}});
document.addEventListener('change',async e=>{if(e.target.id==='filonAuto'){try{await api('/api/filon',{auto:e.target.checked});await refresh(true);toast(e.target.checked?'Filon actualisé toutes les 2 h':'Actualisation automatique arrêtée')}catch(err){toast(err.message)}}});
